#pragma HLS INTERFACE m_axi port=in  offset=slave bundle=gmem max_widen_bitwidth=512 max_read_burst_length=64 num_read_outstanding=16
#pragma HLS INTERFACE m_axi port=out offset=slave bundle=gmem max_widen_bitwidth=512 max_write_burst_length=64 num_write_outstanding=16
// Keep pointer element types unchanged unless the active variant explicitly allows a packed wide-bus ABI.
// After widening, restructure computation around LANES = 512 / element_bitwidth when legal.

#include <ap_int.h>
typedef ap_uint<512> wide_t;
#pragma HLS INTERFACE m_axi port=in  offset=slave bundle=gmem max_widen_bitwidth=512 max_read_burst_length=64 num_read_outstanding=16
#pragma HLS INTERFACE m_axi port=out offset=slave bundle=gmem max_widen_bitwidth=512 max_write_burst_length=64 num_write_outstanding=16
// LANES = 512 / (8 * sizeof(element)); unpack/stage lanes, unroll lane compute, and handle scalar tail explicitly.

float tile[TILE];
load_tile: for (int i = 0; i < TILE; ++i) tile[i] = in[base + i];
compute_tile: for (int i = 0; i < TILE; ++i) {
#pragma HLS PIPELINE II=1
    ... tile[i] ...
}

for (int tile_base = 0; tile_base < N; tile_base += TILE) {
    load_tile: for (int i = 0; i < TILE; ++i) {
#pragma HLS PIPELINE II=1
        if (tile_base + i < N) tile[i] = in[tile_base + i];
    }

    compute_tile: for (int i = 0; i < TILE; ++i) {
#pragma HLS PIPELINE II=1
        if (tile_base + i < N) out_tile[i] = f(tile[i]);
    }

    store_tile: for (int i = 0; i < TILE; ++i) {
#pragma HLS PIPELINE II=1
        if (tile_base + i < N) out[tile_base + i] = out_tile[i];
    }
}

HOT_LOOP: for (int i = 0; i < N; ++i) {
#pragma HLS PIPELINE II=1
    ...
}
// Check achieved II in the synthesis report; if II is blocked, resolve the specific bottleneck.

LOOP: for (int i = 0; i < N; i += UNROLL_FACTOR) {
#pragma HLS PIPELINE II=1
    LANE: for (int lane = 0; lane < UNROLL_FACTOR; ++lane) {
#pragma HLS UNROLL
        int idx = i + lane;
        if (idx < N) out[idx] = f(in[idx]);
    }
}

for (int t = 0; t < NUM_TILES + 1; ++t) {
#pragma HLS DATAFLOW
    if (t < NUM_TILES) load_tile(in, buf[t & 1], t);
    if (t > 0) compute_tile(buf[(t - 1) & 1], out, t - 1);
}

#pragma HLS INTERFACE m_axi port=in  offset=slave bundle=gmem max_widen_bitwidth=512 max_read_burst_length=64 num_read_outstanding=16
#pragma HLS INTERFACE m_axi port=out offset=slave bundle=gmem max_widen_bitwidth=512 max_write_burst_length=64 num_write_outstanding=16
// Do not stop at pragmas: rewrite the compute loop around LANES = 512 / element_bitwidth if safe.

float buf[N];
#pragma HLS ARRAY_PARTITION variable=buf cyclic factor=4 dim=1

LOOP: for (int i = 0; i < N; ++i) {
#pragma HLS PIPELINE II=1
    ... buf[i] ... buf[i + 1] ...
}

LOOP: for (int i = 0; i < N; ++i) {
#pragma HLS PIPELINE II=1
#pragma HLS DEPENDENCE variable=buf inter false
    ...
}
// Use only when non-overlap across iterations is proven.

for (int i = 0; i < runtime_n; ++i) {
#pragma HLS loop_tripcount min=N avg=N max=N
    ...
}

#pragma HLS INTERFACE m_axi port=in  offset=slave bundle=gmem max_widen_bitwidth=512 max_read_burst_length=64 num_read_outstanding=16
#pragma HLS INTERFACE m_axi port=out offset=slave bundle=gmem max_widen_bitwidth=512 max_write_burst_length=64 num_write_outstanding=16

const int LANES = 512 / (8 * sizeof(data_t));
data_t in_lane[LANES];
data_t out_lane[LANES];
#pragma HLS ARRAY_PARTITION variable=in_lane complete dim=1
#pragma HLS ARRAY_PARTITION variable=out_lane complete dim=1

for (int base = 0; base < N; base += LANES) {
#pragma HLS PIPELINE II=1
    for (int lane = 0; lane < LANES; ++lane) {
#pragma HLS UNROLL
        int idx = base + lane;
        if (idx < N) {
            data_t x = in[idx];
            out[idx] = f(x);
        }
    }
}

const int LANES = 512 / (8 * sizeof(data_t));
for (int base = 0; base < N; base += LANES) {
#pragma HLS PIPELINE II=1
    for (int lane = 0; lane < LANES; ++lane) {
#pragma HLS UNROLL
        int idx = base + lane;
        if (idx < N) {
            out[idx] = f(in[idx]);
        }
    }
}

load_loop: for (int i = 0; i < N; ++i) {
#pragma HLS PIPELINE II=1
    local[i] = in[i];
}

compute_loop: for (int i = 0; i < N; ++i) {
#pragma HLS PIPELINE II=1
    local_out[i] = f(local[i]);
}

store_loop: for (int i = 0; i < N; ++i) {
#pragma HLS PIPELINE II=1
    out[i] = local_out[i];
}

const int LANES = 512 / (8 * sizeof(data_t));
data_t partial[LANES];
#pragma HLS ARRAY_PARTITION variable=partial complete dim=1

init: for (int lane = 0; lane < LANES; ++lane) {
#pragma HLS UNROLL
    partial[lane] = 0;
}

main_loop: for (int base = 0; base < N; base += LANES) {
#pragma HLS PIPELINE II=1
    for (int lane = 0; lane < LANES; ++lane) {
#pragma HLS UNROLL
        int idx = base + lane;
        if (idx < N) partial[lane] += f(in[idx]);
    }
}

// Final reduction over partial[lane] values.

data_t lane_buf[LANES];
#pragma HLS ARRAY_PARTITION variable=lane_buf complete dim=1

for (int lane = 0; lane < LANES; ++lane) {
#pragma HLS UNROLL
    ... lane_buf[lane] ...
}

data_t tile[TILE];
data_t out_tile[TILE];
#pragma HLS ARRAY_PARTITION variable=tile cyclic factor=UNROLL_FACTOR dim=1
#pragma HLS ARRAY_PARTITION variable=out_tile cyclic factor=UNROLL_FACTOR dim=1

for (int tile_base = 0; tile_base < N; tile_base += TILE) {
    load_tile: for (int i = 0; i < TILE; ++i) {
#pragma HLS PIPELINE II=1
        int idx = tile_base + i;
        if (idx < N) tile[i] = in[idx];
    }

    compute_tile: for (int i = 0; i < TILE; i += UNROLL_FACTOR) {
#pragma HLS PIPELINE II=1
        lane_loop: for (int lane = 0; lane < UNROLL_FACTOR; ++lane) {
#pragma HLS UNROLL
            int local_idx = i + lane;
            int global_idx = tile_base + local_idx;
            if (local_idx < TILE && global_idx < N) out_tile[local_idx] = f(tile[local_idx]);
        }
    }

    store_tile: for (int i = 0; i < TILE; ++i) {
#pragma HLS PIPELINE II=1
        int idx = tile_base + i;
        if (idx < N) out[idx] = out_tile[i];
    }
}

data_t local_tile[TILE_R + 2 * HALO_R][TILE_C + 2 * HALO_C];
#pragma HLS ARRAY_PARTITION variable=local_tile cyclic factor=UNROLL_C dim=2

for (int r0 = 0; r0 < ROWS; r0 += TILE_R) {
  for (int c0 = 0; c0 < COLS; c0 += TILE_C) {
    // 1. Load tile interior plus halo into local_tile.
    // 2. Rewrite A[r + dr][c + dc] as local_tile[local_r + dr + HALO_R][local_c + dc + HALO_C].
    // 3. Pipeline and optionally unroll compute over valid tile interior.
    // 4. Store only valid outputs.
  }
}

#pragma HLS ARRAY_PARTITION variable=tile cyclic factor=UNROLL_FACTOR dim=1

compute_tile: for (int i = 0; i < TILE; i += UNROLL_FACTOR) {
#pragma HLS PIPELINE II=1
    inner: for (int lane = 0; lane < UNROLL_FACTOR; ++lane) {
#pragma HLS UNROLL
        int local_idx = i + lane;
        if (local_idx < TILE) out_tile[local_idx] = f(tile[local_idx]);
    }
}

for (int t = 0; t < NUM_TILES + 1; ++t) {
#pragma HLS DATAFLOW
    if (t < NUM_TILES) load_tile(in, tile_buf[t & 1], t);
    if (t > 0) compute_tile(tile_buf[(t - 1) & 1], out, t - 1);
}

data_t tile[TILE];
#pragma HLS ARRAY_PARTITION variable=tile cyclic factor=UNROLL_FACTOR dim=1

for (int i = 0; i < TILE; i += UNROLL_FACTOR) {
#pragma HLS PIPELINE II=1
    for (int lane = 0; lane < UNROLL_FACTOR; ++lane) {
#pragma HLS UNROLL
        ... tile[i + lane] ...
    }
}

HOT_LOOP: for (int i = 0; i < N; ++i) {
#pragma HLS PIPELINE II=1
    ...
}
// Then inspect achieved II and resolve the actual bottleneck.

compute_tile: for (int i = 0; i < TILE; ++i) {
#pragma HLS PIPELINE II=1
    ... use local_tile[i] ...
}

OUTER: for (int i = 0; i < N; ++i) {
#pragma HLS PIPELINE II=1
    INNER: for (int j = 0; j < SMALL_BOUND; ++j) {
#pragma HLS UNROLL
        ...
    }
}

load_loop: for (...) {
#pragma HLS PIPELINE II=1
    local[i] = in[i];
}
compute_loop: for (...) {
#pragma HLS PIPELINE II=1
    out_local[i] = f(local[i]);
}

for (int i = 0; i < N; ++i) {
#pragma HLS PIPELINE
    acc = update(acc, in[i]);
}

state_t prev[WINDOW];
state_t curr[WINDOW];
#pragma HLS ARRAY_PARTITION variable=prev complete dim=1

LOOP: for (int i = 0; i < N; ++i) {
#pragma HLS PIPELINE II=2
    ...
}

LOOP: for (int i = 0; i < N; i += UNROLL_FACTOR) {
#pragma HLS PIPELINE II=1
    LANE: for (int lane = 0; lane < UNROLL_FACTOR; ++lane) {
#pragma HLS UNROLL
        int idx = i + lane;
        if (idx < N) out[idx] = f(in[idx]);
    }
}

data_t buf[N];
#pragma HLS ARRAY_PARTITION variable=buf cyclic factor=UNROLL_FACTOR dim=1

LOOP: for (int i = 0; i < N; i += UNROLL_FACTOR) {
#pragma HLS PIPELINE II=1
    for (int lane = 0; lane < UNROLL_FACTOR; ++lane) {
#pragma HLS UNROLL
        ... buf[i + lane] ...
    }
}

data_t partial[UNROLL_FACTOR];
#pragma HLS ARRAY_PARTITION variable=partial complete dim=1

for (int lane = 0; lane < UNROLL_FACTOR; ++lane) {
#pragma HLS UNROLL
    partial[lane] = 0;
}

LOOP: for (int i = 0; i < N; i += UNROLL_FACTOR) {
#pragma HLS PIPELINE II=1
    for (int lane = 0; lane < UNROLL_FACTOR; ++lane) {
#pragma HLS UNROLL
        int idx = i + lane;
        if (idx < N) partial[lane] += f(in[idx]);
    }
}
// Final reduction across partial[lane].

data_t in_buf[PE][ITEMS_PER_PE];
#pragma HLS ARRAY_PARTITION variable=in_buf complete dim=1

PE_LOOP: for (int pe = 0; pe < PE; ++pe) {
#pragma HLS UNROLL
    process_items(in_buf[pe], out_buf[pe]);
}

for (int t = 0; t < NUM_TILES + 2; ++t) {
#pragma HLS DATAFLOW
    if (t < NUM_TILES) load_tile(in, in_buf[t & 1], t);
    if (t > 0 && t <= NUM_TILES) compute_tile(in_buf[(t - 1) & 1], out_buf[(t - 1) & 1], t - 1);
    if (t > 1) store_tile(out_buf[(t - 2) & 1], out, t - 2);
}

data_t buf0[TILE];
data_t buf1[TILE];
data_t* load_buf  = (t & 1) ? buf1 : buf0;
data_t* compute_buf = (t & 1) ? buf0 : buf1;

#pragma HLS DATAFLOW
load_stage(in, load_to_compute);
compute_stage(load_to_compute, compute_to_store);
store_stage(compute_to_store, out);

for (int t = 0; t < NUM_TILES + 2; ++t) {
    if (t < NUM_TILES) load_tile(..., t);
    if (t > 0 && t <= NUM_TILES) compute_tile(..., t - 1);
    if (t > 1) store_tile(..., t - 2);
}

// Example policy:
// high-read input  -> gmem0
// second input     -> gmem1
// output stream    -> gmem2
// small scalars    -> control or shared bundle as appropriate

// Complete: small fully parallel dimension
#pragma HLS ARRAY_PARTITION variable=small_buf complete dim=1

// Cyclic: lane-indexed interleaved access
#pragma HLS ARRAY_PARTITION variable=buf cyclic factor=UNROLL_FACTOR dim=1

// Block: each worker owns a contiguous block
#pragma HLS ARRAY_PARTITION variable=buf block factor=PE dim=1

// In-place neighbor update guardrail:
//   A[i][j] = f(A[i-1][j], A[i][j-1], A[i][j], ...)
// has true carried dependencies across loop iterations.
// Do NOT add DEPENDENCE ... false unless the index proof is explicit.
// Do NOT convert to Jacobi-style double-buffering unless that preserves
// the original algorithm's update order and numerical results.
// Legal first attempt for row-major 2D stencils:
//   1. load previous/current/next rows into local row buffers;
//   2. update current-row buffer left-to-right, preserving A[i][j-1]
//      dependence as a real value dependence;
//   3. write the updated current row back after the j sweep;
//   4. replace division by a compile-time constant with reciprocal
//      multiplication when numerically equivalent for the benchmark.
